import{_ as i,o as r,c as t,ah as n}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse('{"title":"Recherche: Die Schmid-Benko-Chats (Die Protokolle der Nähe)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/thomas-schmid-chats-details.md","filePath":"recherche/thomas-schmid-chats-details.md"}'),a={name:"recherche/thomas-schmid-chats-details.md"};function s(o,e,h,d,l,u){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="recherche-die-schmid-benko-chats-die-protokolle-der-nahe" tabindex="-1">Recherche: Die Schmid-Benko-Chats (Die Protokolle der Nähe) <a class="header-anchor" href="#recherche-die-schmid-benko-chats-die-protokolle-der-nahe" aria-label="Permalink to &quot;Recherche: Die Schmid-Benko-Chats (Die Protokolle der Nähe)&quot;">​</a></h1><p><strong>„Du bist die Hure für die Reichen!“ – Einblicke in ein System der privilegierten Behandlung.</strong></p><p>Die sichergestellten Chat-Nachrichten von Thomas Schmid dokumentieren ein Naheverhältnis zwischen Spitzenpolitik und Großinvestoren, das in der Zweiten Republik Österreichs beispiellos ist. Besonders die Kommunikation mit René Benko liefert tiefe Einblicke in die „Ästhetik der Intervention“.</p><hr><h2 id="zentrale-zitate-und-vorgange" tabindex="-1">Zentrale Zitate und Vorgänge <a class="header-anchor" href="#zentrale-zitate-und-vorgange" aria-label="Permalink to &quot;Zentrale Zitate und Vorgänge&quot;">​</a></h2><h3 id="_1-die-„hure-fur-die-reichen" tabindex="-1">1. Die „Hure für die Reichen“ <a class="header-anchor" href="#_1-die-„hure-fur-die-reichen" aria-label="Permalink to &quot;1. Die „Hure für die Reichen“&quot;">​</a></h3><p>Ein Zitat, das Schmid in einem Chat über seine eigene Rolle im ÖVP-Kabinett schrieb, wurde zum geflügelten Wort für die Vorwürfe der Käuflichkeit:</p><blockquote><p><em>„Du hackelst im ÖVP Kabinett!! Du bist die Hure für die Reichen!“</em> In unserer Mockumentary nutzen wir dieses Zitat als Beleg für das Selbstverständnis einer Elite, die sich als Dienstleister für das große Kapital (Horten, Benko) sieht.</p></blockquote><h3 id="_2-das-jobangebot-als-wahrung" tabindex="-1">2. Das Jobangebot als Währung <a class="header-anchor" href="#_2-das-jobangebot-als-wahrung" aria-label="Permalink to &quot;2. Das Jobangebot als Währung&quot;">​</a></h3><p>Laut Schmids Aussagen bot ihm René Benko Ende 2016 eine Stelle als Generalbevollmächtigter an – mit einem Gehaltspaket von bis zu <strong>600.000 Euro pro Jahr</strong>.</p><ul><li><strong>Der Kontext:</strong> Zur selben Zeit war Schmid im Finanzministerium mit Steuerprüfungen der Signa (Stichwort: „Goldenes Quartier“) befasst.</li><li><strong>Der Verdacht:</strong> Die WKStA untersucht, ob dieses Jobangebot eine Gegenleistung für wohlwollende steuerliche Behandlungen war.</li></ul><h3 id="_3-„wir-sind-fur-rene-benko" tabindex="-1">3. „Wir sind für René Benko“ <a class="header-anchor" href="#_3-„wir-sind-fur-rene-benko" aria-label="Permalink to &quot;3. „Wir sind für René Benko“&quot;">​</a></h3><p>In einem Chat mit Spitzenbeamten stellte Schmid die Strategie des Ministeriums klar:</p><blockquote><p><em>„Wir sind für René Benko. Denke der ist mit HBK [Herr Bundeskanzler Kurz] abgestimmt.“</em> Dieser Satz belegt die politische Weisung von ganz oben, die Interessen des Investors über die neutrale Verwaltung zu stellen.</p></blockquote><hr><h2 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1">Bedeutung für das „Horten-Mysterium“ <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das „Horten-Mysterium“&quot;">​</a></h2><p>Die Chats sind das „moderne Archiv“, das die unterkühlten Verträge Helmut Hortens aus den 1930ern ergänzt.</p><ul><li><strong>Vom Brief zum Emoji:</strong> Während Horten noch förmliche Briefe schrieb, wird Macht heute per WhatsApp und Emojis (🚀, 💪) ausgeübt.</li><li><strong>Der operative Pointillismus:</strong> Die Chats zeigen, wie durch viele kleine Interventionen (E-Mail-Adressen schicken, Termine koordinieren, Akten „besprechen“) das große Bild der Begünstigung entsteht.</li></ul><hr><p><em>Quellen: Einvernahmeprotokolle der WKStA (Thomas Schmid), Berichterstattung von Profil, Standard und ZackZack.</em></p>',20)])])}const g=i(a,[["render",s]]);export{m as __pageData,g as default};
